23	/** The exact on-disk shape from the feature README. Anything else is rejected. */
24	const absoluteDirectory = z.string().min(1).refine(path => !path.includes('\0'), 'must not contain NUL characters')
25	  .refine(path => isAbsolute(path) && !path.startsWith('~'), 'must be an absolute path; "~", environment variables and relative paths are not expanded')
26	  .refine(path => resolve(path) !== sep, 'must not be the filesystem root')
27	
28	const nodeSchema = z.strictObject({
29	  node_id: z.string().regex(ID_PATTERN),
30	  label: z.string().min(1),
31	  kind: z.enum(NODE_KINDS),
32	  depends_on: z.array(z.string().regex(ID_PATTERN)),
33	})
