36	
37	const workflowSchema = z.strictObject({
38	  workflow_id: z.string().regex(ID_PATTERN),
39	  runs_root: absoluteDirectory,
40	  definition: storedDefinitionSchema,
41	})
42	
43	const projectSchema = z.strictObject({
44	  project_id: z.string().regex(ID_PATTERN),
45	  name: z.string().trim().min(1),
46	  repository: absoluteDirectory,
47	  workflows: z.array(workflowSchema),
48	})
